Item.method_code:
const isNewItem = item.getAttribute('action') === 'add';
if (isNewItem) {
	return;
}

const topWindow = aras.getMostTopWindowWithAras(window);
const notify = aras.getNotifyByContext(topWindow);
const notifyInfo = (message) => notify(message, {type: 'info'});

const {itemId, itemTypeName, currentTarget} = options;
const itemLabel = currentTarget.label;

const url = new URL(`${aras.getInnovatorUrl()}?StartItem=${itemTypeName}:${itemId}`);

const linkNode = window.HyperHTMLElement.hyper`<a href="${url.toString()}" >${itemLabel}</a>`;

ArasModules.copyHtmlToBuffer(linkNode);
notifyInfo(aras.getResource('', 'toolbar.message.copied_to_clipboard', itemLabel));
